mapper.update:
update product
set update_time=now(), is_deleted=1
where id=#{id}

mapper.select:
select p.*, b.name brandName,
       c1.name category1Name, c2.name category2Name, c3.name category3Name
from product p
    INNER JOIN brand b ON p.brand_id = b.id
    INNER JOIN category c1 ON p.category1_id=c1.id
    INNER JOIN category c2 ON p.category2_id=c2.id
    INNER JOIN category c3 ON p.category3_id=c3.id


        and p.brand_id=#{brandId}


        and p.category1_id=#{category1Id}


        and p.category2_id=#{category2Id}


        and p.category3_id=#{category3Id}

    and p.is_deleted=0

order by p.id desc
